if(is_file(__DIR__.'/../core/package-integrity.php'))require_once __DIR__.'/../core/package-integrity.php';
$isSuper=devone_app_is_super_admin();
if(function_exists('devone_network_enabled')&&devone_network_enabled()&&!$isSuper&&function_exists('devone_license_plan_at_least')&&!devone_license_plan_at_least('pro')){http_response_code(403);exit('DevOne Apps on a network installation requires a Pro or Enterprise license.');}
$currentSite=function_exists('devone_admin_current_site_id')?max(1,(int)devone_admin_current_site_id()):devone_app_site_id();
function devone_apps_rrmdir($d){if(!is_dir($d))return true;foreach(scandir($d)?:array()as$i){if($i==='.'||$i==='..')continue;$p=$d.DIRECTORY_SEPARATOR.$i;is_dir($p)&&!is_link($p)?devone_apps_rrmdir($p):@unlink($p);}return@rmdir($d);}function devone_apps_copy($s,$d){if(!is_dir($d)&&!@mkdir($d,0775,true))return false;foreach(scandir($s)?:array()as$i){if($i==='.'||$i==='..')continue;$a=$s.DIRECTORY_SEPARATOR.$i;$b=$d.DIRECTORY_SEPARATOR.$i;if(is_dir($a)){if(!devone_apps_copy($a,$b))return false;}elseif(!@copy($a,$b))return false;}return true;}function devone_apps_package_root($t){if(is_file($t.'/app.json'))return$t;$dirs=array_values(array_filter(glob($t.'/*')?:array(),'is_dir'));return count($dirs)===1&&is_file($dirs[0].'/app.json')?$dirs[0]:'';}
function devone_apps_install_zip($zip,$sha,$siteId,&$error){$error='';if($sha!==''&&!preg_match('/^[a-f0-9]{64}$/i',$sha)){$error='SHA-256 must contain 64 hexadecimal characters.';return false;}if($sha!==''&&!hash_equals(strtolower($sha),strtolower(hash_file('sha256',$zip)))){$error='SHA-256 checksum does not match.';return false;}$report=array();if(function_exists('devone_package_scan_zip')&&!devone_package_scan_zip($zip,$error,$report))return false;$tmp=sys_get_temp_dir().'/devone-app-'.bin2hex(random_bytes(8));@mkdir($tmp,0700,true);if(!function_exists('safe_zip_extract_with_error')||!safe_zip_extract_with_error($zip,$tmp,$error)){devone_apps_rrmdir($tmp);if($error==='')$error='ZIP extraction failed.';return false;}$pkg=devone_apps_package_root($tmp);if($pkg===''){devone_apps_rrmdir($tmp);$error='Package must contain app.json at its root.';return false;}if(function_exists('devone_verify_extracted_manifest')&&!devone_verify_extracted_manifest($pkg,$error)){devone_apps_rrmdir($tmp);return false;}$raw=json_decode((string)file_get_contents($pkg.'/app.json'),true);$folder=devone_app_slug($raw['slug']??$raw['name']??'','');if($folder===''){devone_apps_rrmdir($tmp);$error='App slug is invalid.';return false;}$dest=devone_app_base_path().DIRECTORY_SEPARATOR.$folder;$existing=is_dir($dest);$wasActive=0;try{$q=db()->prepare('SELECT active FROM `'.table_name('apps').'` WHERE site_id=? AND folder=?');$q->execute(array($siteId,$folder));$wasActive=(int)$q->fetchColumn();}catch(Throwable$e){}if($existing&&!devone_apps_rrmdir($dest)){devone_apps_rrmdir($tmp);$error='Existing app could not be replaced.';return false;}if(!devone_apps_copy($pkg,$dest)){devone_apps_rrmdir($tmp);$error='App files could not be installed.';return false;}devone_apps_rrmdir($tmp);unset($GLOBALS['devone_app_manifests'][$folder]);if(!devone_app_validate($folder,$error)){devone_apps_rrmdir($dest);return false;}$m=devone_app_manifest($folder,true);$life='';if(!devone_app_run_lifecycle($folder,$existing?'update':'install',array('upgrade'=>$existing,'site_id'=>$siteId,'network_scope'=>$siteId===0),$life)){devone_app_upsert($folder,$m,0,'error',$life,$siteId);$error=$life;return false;}devone_app_upsert($folder,$m,$wasActive,$wasActive?'active':'installed','',$siteId);if(function_exists('devone_log'))devone_log($existing?'app_updated':'app_installed',$folder.' site_scope='.$siteId);return$folder;}
function devone_apps_fetch_https($url,&$error){$error='';$current=trim((string)$url);for($r=0;$r<=3;$r++){$parts=parse_url($current);if(strtolower((string)($parts['scheme']??''))!=='https'||empty($parts['host'])){$error='Only HTTPS package URLs are allowed.';return false;}$ctx=stream_context_create(array('http'=>array('timeout'=>45,'follow_location'=>0,'ignore_errors'=>true,'user_agent'=>'DevOne Apps/1.7.4'),'ssl'=>array('verify_peer'=>true,'verify_peer_name'=>true)));$data=@file_get_contents($current,false,$ctx);$headers=isset($http_response_header)&&is_array($http_response_header)?$http_response_header:array();$status=0;if(!empty($headers[0])&&preg_match('#\s([0-9]{3})(?:\s|$)#',(string)$headers[0],$m))$status=(int)$m[1];if($data!==false&&$status>=200&&$status<300){if(strlen((string)$data)>104857600){$error='Package exceeded 100 MB.';return false;}return$data;}if($status>=300&&$status<400&&$r<3){$loc='';foreach($headers as$h){if(stripos((string)$h,'Location:')===0){$loc=trim(substr((string)$h,9));break;}}if($loc!==''){if(strpos($loc,'//')===0)$loc='https:'.$loc;elseif(strpos($loc,'/')===0)$loc='https://'.(string)($parts['host']??'').(!empty($parts['port'])?':'.(int)$parts['port']:'').$loc;$np=parse_url($loc);if(strtolower((string)($np['scheme']??''))!=='https'){$error='A package redirect attempted to leave HTTPS.';return false;}$current=$loc;continue;}}$error='Package download failed'.($status?' (HTTP '.$status.')':'.');return false;}$error='Package download exceeded the redirect limit.';return false;}
$msg='';$error='';$scope=$currentSite;if($isSuper&&isset($_REQUEST['scope'])&&$_REQUEST['scope']==='network')$scope=0;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$folder=devone_app_slug($_POST['folder']??'','');$scope=$isSuper&&($_POST['scope']??'')==='network'?0:$currentSite;if($action==='upload'){if(empty($_FILES['app_zip']['tmp_name'])||!is_uploaded_file($_FILES['app_zip']['tmp_name']))$error='Choose an App ZIP.';else{$installed=devone_apps_install_zip($_FILES['app_zip']['tmp_name'],trim((string)($_POST['sha256']??'')),$scope,$error);if($installed)$msg='App installed: '.$installed;}}elseif($action==='cdn'){$url=trim((string)($_POST['url']??''));$parts=parse_url($url);if(($parts['scheme']??'')!=='https')$error='Only HTTPS package URLs are allowed.';else{$tmp=tempnam(sys_get_temp_dir(),'devone-app-');$data=devone_apps_fetch_https($url,$error);if($data===false)$error=$error?:'Package download failed.';else{file_put_contents($tmp,$data,LOCK_EX);$installed=devone_apps_install_zip($tmp,trim((string)($_POST['sha256']??'')),$scope,$error);@unlink($tmp);if($installed)$msg='App downloaded and installed: '.$installed;}}}elseif($action==='activate'&&$folder!==''){$e='';if(!devone_app_validate($folder,$e))$error=$e;else{$life='';if(!devone_app_run_lifecycle($folder,'activate',array('site_id'=>$scope,'network_scope'=>$scope===0),$life))$error=$life;else{devone_app_set_state($folder,1,'active','',$scope);$msg='App activated.';}}}elseif($action==='deactivate'&&$folder!==''){$life='';if(!devone_app_run_lifecycle($folder,'deactivate',array('site_id'=>$scope),$life))$error=$life;else{devone_app_set_state($folder,0,'inactive','',$scope);$msg='App deactivated.';}}elseif($action==='uninstall'&&$folder!==''){$life='';devone_app_run_lifecycle($folder,'deactivate',array('site_id'=>$scope,'reason'=>'uninstall'),$life);if($life==='')devone_app_run_lifecycle($folder,'uninstall',array('site_id'=>$scope,'purge_data'=>!empty($_POST['purge'])),$life);if($life!=='')$error=$life;else{db()->prepare('DELETE FROM `'.table_name('apps').'` WHERE site_id=? AND folder=?')->execute(array($scope,$folder));if(!empty($_POST['purge']))devone_apps_rrmdir(devone_app_storage_path($folder,$scope));$remaining=db()->prepare('SELECT COUNT(*) FROM `'.table_name('apps').'` WHERE folder=?');$remaining->execute(array($folder));if((int)$remaining->fetchColumn()===0)devone_apps_rrmdir(devone_app_root($folder));$msg='App assignment uninstalled.';}}elseif($action==='sync'){$msg='App registry synchronized: '.devone_app_sync_disk($scope).' found.';}}
$s=db()->prepare('SELECT * FROM `'.table_name('apps').'` WHERE site_id=? ORDER BY name');$s->execute(array($scope));$apps=$s->fetchAll();
devone_admin_header('Apps - DevOne CMS');?>
