<div class="apps-grid"><section><div class="section-head"><h2><?=$scope===0?'Network-wide Apps':'Site Apps'?></h2><span><?=count($apps)?></span></div><?php if(!$apps):?><div class="card"><p>No apps are assigned to this scope.</p></div><?php endif;?><?php foreach($apps as$a):$caps=json_decode((string)$a['capabilities'],true)?:array();?><div class="card app-card"><div><h3><?=e($a['name'])?></h3><p><?=e($a['description'])?></p><div class="app-meta"><span>v<?=e($a['version'])?></span><span><?=e($a['status'])?></span><span class="code"><?=e($a['mount_path'])?></span><span><?=count($caps)?> capabilities</span></div><?php if($a['last_error']):?><p class="notice error"><?=e($a['last_error'])?></p><?php endif;?></div><div class="app-actions"><form method="post"><?=csrf_field()?><input type="hidden" name="scope" value="<?=$scope===0?'network':'site'?>"><input type="hidden" name="folder" value="<?=e($a['folder'])?>"><input type="hidden" name="action" value="<?=$a['active']?'deactivate':'activate'?>"><button class="button"><?=$a['active']?'Deactivate':'Activate'?></button></form><form method="post" onsubmit="return confirm('Uninstall this app assignment?');"><?=csrf_field()?><input type="hidden" name="scope" value="<?=$scope===0?'network':'site'?>"><input type="hidden" name="folder" value="<?=e($a['folder'])?>"><input type="hidden" name="action" value="uninstall"><label><input type="checkbox" name="purge" value="1"> purge storage</label><button class="button danger">Uninstall</button></form></div></div><?php endforeach;?></section><aside><div class="card"><h2>Upload App</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="scope" value="<?=$scope===0?'network':'site'?>"><input type="hidden" name="action" value="upload"><label>App ZIP<input type="file" name="app_zip" accept=".zip" required></label><label>Expected SHA-256<input name="sha256" maxlength="64"></label><button class="button primary">Install ZIP</button></form></div><div class="card"><h2>Install from CDN</h2><form method="post"><?=csrf_field()?><input type="hidden" name="scope" value="<?=$scope===0?'network':'site'?>"><input type="hidden" name="action" value="cdn"><label>HTTPS package URL<input type="url" name="url" required></label><label>Expected SHA-256<input name="sha256" maxlength="64"></label><button class="button primary">Download & Install</button></form></div><div class="card"><h2>Scope</h2><p><?=$scope===0?'Installed for every site unless a site-specific route takes precedence.':'Installed only for the currently selected site.'?></p><form method="post"><?=csrf_field()?><input type="hidden" name="scope" value="<?=$scope===0?'network':'site'?>"><input type="hidden" name="action" value="sync"><button class="button">Sync Registry</button></form></div></aside></div><?php devone_admin_footer();
